/bin/bash -lc "python3 - <<'PY'
import ast, hashlib, importlib.util, json
from pathlib import Path
p=json.loads(Path('proposal.json').read_text())
r=json.load(open('/tmp/r001-resolved.json'))
print('jsonschema_available',importlib.util.find_spec('jsonschema') is not None)
print('torch_available',importlib.util.find_spec('torch') is not None)
# Validate schema structure directly, without installing dependencies.
def validate(value,schema,path='"'$'"'):
 t=schema.get('type')
 ok={'object':lambda:isinstance(value,dict),'array':lambda:isinstance(value,list),'string':lambda:isinstance(value,str),'boolean':lambda:isinstance(value,bool)}
 if t: assert ok[t](),(path,'type',t)
 if 'const' in schema: assert value==schema['const'],(path,'const')
 if 'enum' in schema: assert value in schema['enum'],(path,'enum')
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),path
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),path
  if 'items' in schema:
   for i,v in enumerate(value): validate(v,schema['items'],f'{path}[{i}]')
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=value.keys(),(path,'required')
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False: assert set(value)<=props.keys(),(path,'extra')
  for k,v in value.items():
   if k in props: validate(v,props[k],path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
normalized=[]
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
for v in p['variants']:
 file=Path(v['file']); assert file.name==str(file) and file.suffix=='.py'
 text=file.read_text();tree=ast.parse(text)
 compile(text,str(file),'exec')
 config=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert config==v['config']
 init=next(n for n in ast.walk(tree) if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 defaults=dict(zip([a.arg for a in init.args.args][-len(init.args.defaults):],init.args.defaults))
 for key,val in config.items():
  default=ast.literal_eval(defaults[key]); assert default==val or isinstance(default,tuple) and list(default)==val,(file,key)
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(x.name.split('.')[0] in allowed for x in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in allowed
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','__import__'}
 for n in tree.body:
  if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets): n.value=ast.Constant(None)
 defaults['routing'].value='FACTORED'
 defaults['empty_slot_inputs'].value='FACTORED'
 normalized.append(ast.dump(tree,include_attributes=False))
 print(file.name, 'syntax/config/import checks pass',hashlib.sha256(text.encode()).hexdigest())
assert len(set(normalized))==1,'Unexpected factorial source difference'
# Original public ancestor hashes must stay unchanged.
for h in r['context']['history']:
 filename='history_'+h['id'].replace('-','_')+'.py'
 if h['id']=='baseline-din': filename='history_baseline_din.py'
 # File names have trial separator underscores already.
 path=Path(filename)
 if path.exists(): assert hashlib.sha256(path.read_bytes()).hexdigest()==h['source_sha256'],path
print('study schema, evidence IDs and factorial AST parity pass')
PY"

